import { EChart, type EChartSetup } from "@/components/ui/echart"
import * as echarts from "echarts"
import type { EChartsOption } from "echarts"

// Adapted from the Apache ECharts example "Stacked Bar Normalization" (Apache-2.0):
// https://echarts.apache.org/examples/en/editor.html?c=bar-stack-normalization
const setup: EChartSetup = () => {
  let option!: EChartsOption
  // There should not be negative values in rawData
  const rawData = [
      [100, 302, 301, 334, 390, 330, 320],
      [320, 132, 101, 134, 90, 230, 210],
      [220, 182, 191, 234, 290, 330, 310],
      [150, 212, 201, 154, 190, 330, 410],
      [820, 832, 901, 934, 1290, 1330, 1320]
  ];
  const totalData: number[] = [];
  for (let i = 0; i < rawData[0].length; ++i) {
      let sum = 0;
      for (let j = 0; j < rawData.length; ++j) {
          sum += rawData[j][i];
      }
      totalData.push(sum);
  }

  const series: echarts.BarSeriesOption[] = [
      'Direct',
      'Mail Ad',
      'Affiliate Ad',
      'Video Ad',
      'Search Engine'
  ].map((name, sid) => {
      return {
          name,
          type: 'bar',
          stack: 'total',
          barWidth: '60%',
          label: {
              show: true,
              formatter: (params: any) => Math.round(params.value * 1000) / 10 + '%'
          },
          data: rawData[sid].map((d, did) =>
          totalData[did] <= 0 ? 0 : d / totalData[did]
          )
      };
  });

  option = {
      legend: {
          selectedMode: false
      },
      yAxis: {
          type: 'value'
      },
      xAxis: {
          type: 'category',
          data: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']
      },
      series
  };
  return option
}

export function EchartsBarStackNormalization() {
  return <EChart setup={setup} />
}
